    for c in range(3,13):
        g[r][c]=8
# Restore original frame color 3 on its perimeter; interior is 8 already.
for c in range(5,11):
    g[6][c]=3; g[11][c]=3
for r in range(6,12):
    g[r][5]=3; g[r][10]=3
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

